import { CorruptError, OpfsqlError } from "../../errors.js";

// ---------------------------------------------------------------------------
// Stored statements and index keys are generated by opfsql, so one that does
// not parse or bind means the files are damaged: its statement error is
// reported as corruption. A bug (INTERNAL) stays a bug.
// ---------------------------------------------------------------------------

/** True for an error a statement's text or meaning causes, not a bug. */
export function isStatementError(error: unknown): error is OpfsqlError {
  return error instanceof OpfsqlError && error.code !== "INTERNAL";
}

/** `run()`, a statement error in it reported as corruption `described`. */
export function asCorruption<T>(
  run: () => T,
  described: (problem: string) => string,
): T {
  try {
    return run();
  } catch (error) {
    if (!isStatementError(error)) throw error;
    throw new CorruptError(described(error.message));
  }
}
